import{_ as i,a0 as s,w as p,s as d,ao as l,I as t,x as r,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux free 命令 - 顯示系統中空閒和已使用的內存 | LCTT x X-CMD","titleTemplate":false,"description":"Linux free 命令 - 顯示系統中空閒和已使用的內存 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux free 命令 - 顯示系統中空閒和已使用的內存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux free 命令 - 顯示系統中空閒和已使用的內存 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linux free Command - Display Free and used Memory in the System","title":"Linux free 命令 - 顯示系統中空閒和已使用的內存","tag":"201401","desc":""},"relativePath":"201401/Linux free Command - Display Free and used Memory in the System.md","filePath":"[post].md"}'),f={name:"201401/Linux free Command - Display Free and used Memory in the System.md"};function m(u,e,g,h,x,b){const n=s("Link");return p(),d("div",null,[e[21]||(e[21]=l(`<h1 id="linux-free-命令-顯示系統中空閒和已使用的內存" tabindex="-1">Linux free 命令 - 顯示系統中空閒和已使用的內存 <a class="header-anchor" href="#linux-free-命令-顯示系統中空閒和已使用的內存" aria-label="Permalink to “Linux free 命令 - 顯示系統中空閒和已使用的內存”">​</a></h1><p>系統管理員必須維護他們服務器的健康運行。其中一個重要的部分就是內存。當服務器內存使用率過高時，它會降低服務器的性能。Linux有一個稱為 <strong>free</strong> 的工具，來監控內存使用率。</p><h3 id="free-命令是什麼" tabindex="-1">free 命令是什麼 <a class="header-anchor" href="#free-命令是什麼" aria-label="Permalink to “free 命令是什麼”">​</a></h3><p><strong>free</strong> 命令是一個顯示系統中空閒和已用內存大小的工具。free 命令的輸出和 top 命令相似。大多數Linux發行版已經含有 free 命令。</p><h3 id="如何運行-free" tabindex="-1">如何運行 free <a class="header-anchor" href="#如何運行-free" aria-label="Permalink to “如何運行 free”">​</a></h3><p>想要運行，只需在控制台輸入<strong>free</strong> 即可。不帶選項運行會顯示一個以KB為單位的默認輸出。</p><pre><code>$ free
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_default.png" alt="free默認視圖"></p><p>從上面的截圖我們看到：</p><h4 id="內存-以kb計" tabindex="-1">內存 (以KB計) <a class="header-anchor" href="#內存-以kb計" aria-label="Permalink to “內存 (以KB計)”">​</a></h4><ul><li>Total（全部） : 1026740</li><li>Used（已用） : 843396</li><li>Free（可用） : 183344</li><li>Shared（共享） : 0</li><li>Buffers（塊設備緩存區） : 52704</li><li>Cached（文件緩存） : 376384</li></ul>`,11)),t("p",null,[e[1]||(e[1]=r("譯註：關於Buffers和Cached的區別，來自 ",-1)),a(n,{href:"http://www.taobaotesting.com/blogs/qa?bid=2265"},{default:o(()=>[...e[0]||(e[0]=[r("http://www.taobaotesting.com/blogs/qa?bid=2265",-1)])]),_:1}),e[2]||(e[2]=r(" 的一段解釋如下：",-1))]),e[22]||(e[22]=l(`<blockquote><p>buffers是指用來給塊設備做的緩衝大小，他只記錄文件系統的metadata以及 tracking in-flight pages.</p></blockquote><blockquote><p>cached是用來給文件做緩衝。</p></blockquote><blockquote><p>那就是説：buffers是用來存儲，目錄裏面有什麼內容，權限等等。而cached直接用來記憶我們打開的文件</p></blockquote><h4 id="swap-以kb計" tabindex="-1">Swap (以KB計) <a class="header-anchor" href="#swap-以kb計" aria-label="Permalink to “Swap (以KB計)”">​</a></h4><ul><li>Total（全部） : 1045500</li><li>Used（已用） : 3376</li><li>Free（可用） : 1042124</li></ul><p>當你看見 buffer/cache 的空閒空間低或者 swap 的空閒空間低，説明內存需要升級了。這意味這內存利用率很高。請注意 <strong>shared（共享）內存列應該被忽略</strong> ，因為它已經被廢棄了。</p><h3 id="以其它單元顯示內存信息" tabindex="-1">以其它單元顯示內存信息 <a class="header-anchor" href="#以其它單元顯示內存信息" aria-label="Permalink to “以其它單元顯示內存信息”">​</a></h3><p>如我們先前提到的，默認 free 會以 KB 為單位顯示信息。free 同樣提供給我們 <strong>b (B), -k (KB), -m (MB), -g (GB) and –tera (TB)</strong>這些單位。要顯示我們想要的單位，只要選擇一個並在 free 後面跟上。下面一個是以 MB 為單位的輸出樣例。</p><pre><code>$ free -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_m.png" alt="free命令以MB為單位"></p><p>這個技巧同樣適用於<strong>-b, -k, -g</strong> 以及 <strong>–tera</strong> 選項。</p><h3 id="以適於人類可讀方式顯示內存信息" tabindex="-1">以適於人類可讀方式顯示內存信息 <a class="header-anchor" href="#以適於人類可讀方式顯示內存信息" aria-label="Permalink to “以適於人類可讀方式顯示內存信息”">​</a></h3><p>free 同樣提供了<strong>-h</strong>選項，這意味着適於人類可讀(譯註:系統上可能並不存在-h選項，已被-m取代)。那麼這與其它的選項有什麼不同呢，如<strong>-m</strong>(MB)選項？ 可見的最大不同是<strong>-h</strong>選項會在數字後面加上適於人類可讀的單位。讓我們看一個例子。</p><pre><code>$ free -h
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_h.png" alt="人類可讀的free"></p><p>如我們一起看到的，在1,0數字後這裏是<strong>G(GB)</strong>字母。當數字並沒有達到GB時，free足夠聰明來知道並在每個數字後面跟上合適的單位。後面的<strong>M</strong> - 數字929告訴我們它有929MB(譯註: 原文為929 number tell us its 969 Megabytes，這裏應該為輸入錯誤)。</p><h3 id="間隔顯示-free" tabindex="-1">間隔顯示 free <a class="header-anchor" href="#間隔顯示-free" aria-label="Permalink to “間隔顯示 free”">​</a></h3><p>作為一個狀態檢查工具，最好的統計內存利用率的方法是使用延遲間隔。這麼做的話，我們可以使用<strong>-s</strong>選項後面跟上我們想要間隔的N秒數。我們可以在後面合併幾個選項來使輸出滿足我們的需求。假如我們想要每3秒統計一次內存利用率並且適於人類可讀，那麼就像這樣做:</p><pre><code>$ free -hs 3
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_hs3.png" alt="間隔3s顯示free"></p><h3 id="顯示高低內存利用率" tabindex="-1">顯示高低內存利用率 <a class="header-anchor" href="#顯示高低內存利用率" aria-label="Permalink to “顯示高低內存利用率”">​</a></h3><p>如果我們想要知道高低內存統計，我們可以使用-l選項。下面是一個例子。</p><pre><code>$ free -l
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_l.png" alt="Free 的 低-高 統計"></p><h3 id="顯示-linux-全部內存" tabindex="-1">顯示 Linux 全部內存 <a class="header-anchor" href="#顯示-linux-全部內存" aria-label="Permalink to “顯示 Linux 全部內存”">​</a></h3><p>如果我們需要每列的總計信息，我們可以在 free 命令後面跟上 <strong>-t</strong> 選項。這會在字底部額外加入一行顯示。</p><pre><code>$ free -t
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_t.png" alt="free命令帶總計內存"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,29)),t("p",null,[e[4]||(e[4]=r("除了",-1)),a(n,{href:"http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/"},{default:o(()=>[...e[3]||(e[3]=[r("vmstat",-1)])]),_:1}),e[5]||(e[5]=r("以外，free 命令也是一個用於統計內存利用率的簡單統計工具。用這個你可以快速查看你的 Linux 內存信息。free 命令使用 ",-1)),e[6]||(e[6]=t("strong",null,"/proc/meminfo",-1)),e[7]||(e[7]=r(" 作為基準來顯示內存利用率信息。如往常一樣，你可以在控制台下輸入 ",-1)),e[8]||(e[8]=t("strong",null,"man free",-1)),e[9]||(e[9]=r(" 來獲取更多關於 free 的信息。",-1))]),e[23]||(e[23]=t("hr",null,null,-1)),t("p",null,[e[11]||(e[11]=r("via: ",-1)),a(n,{href:"http://linoxide.com/linux-command/linux-free-command/"},{default:o(()=>[...e[10]||(e[10]=[r("http://linoxide.com/linux-command/linux-free-command/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=r("譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:o(()=>[...e[12]||(e[12]=[r("geekpi",-1)])]),_:1}),e[15]||(e[15]=r(" 校對：",-1)),a(n,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[13]||(e[13]=[r("Caroline",-1)])]),_:1})]),t("p",null,[e[18]||(e[18]=r("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[16]||(e[16]=[r("LCTT",-1)])]),_:1}),e[19]||(e[19]=r(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:o(()=>[...e[17]||(e[17]=[r("Linux中國",-1)])]),_:1}),e[20]||(e[20]=r(" 榮譽推出",-1))])])}const C=i(f,[["render",m]]);export{L as __pageData,C as default};
